//! Byte-for-byte conformance against `reference/vectors/05-mosaic/`
//! (`layout.json`, `batch.json`), generated by
//! `reference/gen_vectors_05_06.py`. Mirrors the 05 parts of
//! `reference/tests/test_vectors_05_06.py`; the batch vector is also
//! re-proven, not only re-verified.

use std::collections::BTreeMap;
use std::path::PathBuf;

use om_field::K;
use om_mosaic::{
    BatchProof, Claim, batch_prove, batch_verify, build_g, compute_layout, lift_point,
};
use om_sumcheck::SumcheckProof;
use om_transcript::Transcript;
use serde_json::Value;

fn load(name: &str) -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../reference/vectors/05-mosaic")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    serde_json::from_str(&text).unwrap()
}

fn k(v: &Value) -> K {
    K::from_hex(v.as_str().unwrap()).unwrap()
}

fn ks(v: &Value) -> Vec<K> {
    v.as_array().unwrap().iter().map(k).collect()
}

fn hexes(xs: &[K]) -> Vec<String> {
    xs.iter().map(|x| x.to_hex()).collect()
}

fn bits(s: &str) -> Vec<bool> {
    s.chars()
        .map(|c| match c {
            '0' => false,
            '1' => true,
            _ => panic!("bad bit {c}"),
        })
        .collect()
}

#[test]
fn layout_vectors() {
    let v = load("layout.json");
    for vec in v["vectors"].as_array().unwrap() {
        let comps: Vec<(i64, usize)> = vec["components"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| (c[0].as_i64().unwrap(), c[1].as_u64().unwrap() as usize))
            .collect();
        let ell_min = vec["ell_min"].as_u64().unwrap() as usize;
        let lay = compute_layout(&comps, ell_min);
        assert_eq!(lay.ell as u64, vec["ell"].as_u64().unwrap());
        let got: Vec<[i64; 4]> = lay
            .placements
            .iter()
            .map(|p| {
                [
                    p.comp_id,
                    p.log_size as i64,
                    p.offset as i64,
                    p.suffix as i64,
                ]
            })
            .collect();
        let expect: Vec<[i64; 4]> = vec["placements"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| {
                let a = p.as_array().unwrap();
                [
                    a[0].as_i64().unwrap(),
                    a[1].as_i64().unwrap(),
                    a[2].as_i64().unwrap(),
                    a[3].as_i64().unwrap(),
                ]
            })
            .collect();
        assert_eq!(got, expect);
    }
}

#[test]
fn batch_vector_replay() {
    let v = load("batch.json");
    for vec in v["vectors"].as_array().unwrap() {
        let tables: BTreeMap<i64, Vec<bool>> = vec["tables"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(id, t)| (id.parse().unwrap(), bits(t.as_str().unwrap())))
            .collect();
        // As in the Python replay: log size from the table length.
        let comps: Vec<(i64, usize)> = tables
            .iter()
            .map(|(&id, t)| (id, t.len().trailing_zeros() as usize))
            .collect();
        let lay = compute_layout(&comps, 0);
        assert_eq!(lay.ell as u64, vec["ell"].as_u64().unwrap());
        let g = build_g(&lay, &tables);
        assert_eq!(g, bits(vec["G"].as_str().unwrap()), "G");

        let claims: Vec<Claim> = vec["claims"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| Claim {
                comp_id: c["id"].as_i64().unwrap(),
                point: ks(&c["point"]),
                value: k(&c["value"]),
            })
            .collect();
        for (c, lifted) in claims.iter().zip(vec["lifted_points"].as_array().unwrap()) {
            assert_eq!(hexes(&lift_point(&lay, c).unwrap()), hexes(&ks(lifted)));
        }

        let label = vec["protocol_label"].as_str().unwrap().as_bytes();

        // Prover output byte-for-byte: round messages, r_G, v_G and the
        // post-protocol transcript state.
        let mut pt = Transcript::new_default(label);
        let (proof, r_g, v_g) = batch_prove(&lay, &claims, &g, &mut pt);
        let got_msgs: Vec<Vec<String>> =
            proof.sumcheck.round_msgs.iter().map(|m| hexes(m)).collect();
        let expect_msgs: Vec<Vec<String>> = vec["round_msgs"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| hexes(&ks(m)))
            .collect();
        assert_eq!(got_msgs, expect_msgs, "round msgs");
        assert_eq!(hexes(&r_g), hexes(&ks(&vec["r_G"])), "r_G");
        assert_eq!(v_g.to_hex(), k(&vec["v_G"]).to_hex(), "v_G");
        assert_eq!(proof.v_g, v_g);
        assert_eq!(
            pt.challenge_k(b"vec/final").to_hex(),
            vec["transcript_final"].as_str().unwrap(),
            "prover transcript final"
        );

        // Verifier on the vector's own proof (the Python replay).
        let vec_proof = BatchProof {
            sumcheck: SumcheckProof {
                round_msgs: vec["round_msgs"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(ks)
                    .collect(),
            },
            v_g: k(&vec["v_G"]),
        };
        let mut vt = Transcript::new_default(label);
        let (r_g2, v_g2) = batch_verify(&lay, &claims, &vec_proof, &mut vt).unwrap();
        assert_eq!(hexes(&r_g2), hexes(&ks(&vec["r_G"])), "verifier r_G");
        assert_eq!(v_g2, v_g);
        assert_eq!(
            vt.challenge_k(b"vec/final").to_hex(),
            vec["transcript_final"].as_str().unwrap(),
            "verifier transcript final"
        );
    }
}
